#!/usr/bin/env python3
"""Freeze and reserve a daily fast/slow EMA crossover grid before evaluation."""
import gzip,hashlib,json,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry
def utc():return datetime.now(timezone.utc).isoformat().replace('+00:00','Z')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,o):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(o,indent=2,ensure_ascii=False,allow_nan=False)+'\n')

# Reuse a successful recent public GET exchangeInfo capture from the paper10 journal.
obs=ROOT/'research/paper10/observations/20261014T081319010144Z';compressed=obs/'exchange_info.json.gz'
raw=gzip.decompress(compressed.read_bytes());meta=json.loads(raw);prov=json.loads((obs/'http_provenance.json').read_text())
source=next(x for x in prov if '/api/v3/exchangeInfo' in x['url'])
assert source['method']=='GET' and source['status']==200 and source['raw_response_sha256']==hashlib.sha256(raw).hexdigest()
assert {x['symbol'] for x in meta['symbols']}=={'BTCUSDT','ETHUSDT'}
for s in meta['symbols']:assert s['status']=='TRADING' and s.get('isSpotTradingAllowed',True)
raw_path=R/'exchange_info_raw.json';raw_path.write_bytes(raw)
exchange={'observation_source':str(compressed.relative_to(ROOT)),'url':source['url'],'method':'GET','captured_at_utc':source['received_at_utc'],'raw_sha256':sha(raw_path),'filters':{a:{f['filterType']:f for f in next(s for s in meta['symbols'] if s['symbol']==a+'USDT')['filters']} for a in ('BTC','ETH')}}
write(R/'exchange_filters.json',exchange)

source_round=ROOT/'research/experiments/20261013T164415Z';source_plan=json.loads((source_round/'plan.json').read_text());data_files=source_plan['data_files']
for asset,files in data_files.items():
 for item in files:
  p=ROOT/item['path'];assert p.is_file() and p.stat().st_size==item['bytes'] and sha(p)==item['sha256']
start='2025-09-19T00:01:00Z';end='2026-09-14T00:01:00Z'
fast_spans=[5,10,20];slow_spans=[40,80,160];assets=['BTC','ETH']
rule={'indicator':'Recursive EMA: alpha=2/(span+1), seed EMA[0]=the first completed UTC daily close, EMA[j]=alpha*close[j]+(1-alpha)*EMA[j-1], Python float adjust=False, initialized once from the first archived daily close and never reset at folds.','entry':'At the close of a fully completed UTC daily bar j, if EMA_fast[j] is strictly greater than EMA_slow[j] and the account is flat, set desired-long. Equality preserves previous desired state.','exit':'At the close of a fully completed UTC daily bar j, if EMA_fast[j] is strictly below EMA_slow[j] while long, set desired-cash. Equality preserves prior desired. No stop, target, confirmation counter, cooldown, overlap or scale-in.','timing':'The daily close is available at the next UTC 00:00; execute at the following UTC 00:01 one-minute open, exactly 60 seconds later. That historical open is only a historical-backtest reference. Warmup establishes indicators but produces no pre-OOS trade.','account':'One separate 2,000-USDT long-only spot account per asset/span configuration. The raw weight is 100% of that account to the named single asset when long. Full affordable LOT_SIZE-floored amount is bought, all units are sold at exit. No leverage, shorting, borrowing, transfer, yield, cross-asset rebalancing or shared impact.','terminal':'Liquidate any position at the declared common terminal UTC 00:01 reference with full modeled costs.'}
cost={'initial_capital_usdt':2000,'fee_per_side':0.001,'estimated_half_spread_per_side':0.0001,'slippage_per_side':0.0002,'impact_model':'0.5 * sample standard deviation(previous 20 complete UTC daily log returns) * sqrt(order quote budget / mean quote volume(previous 20 complete UTC days))','maximum_participation':0.001,'multipliers':[1,2,3],'all_cost_terms_scaled_together':True,'exchange_filter_file':'research/experiments/'+R.name+'/exchange_filters.json','exchange_info_raw_sha256':sha(raw_path),'historical_l2':'unavailable; spread, slippage and immediate fill are modeled assumptions','funding_borrow':'Not applicable to unlevered long-only spot.'}
gates={'all_1x_2x_3x_net_returns_positive':True,'minimum_positive_1x_folds':8,'folds':12,'maximum_3x_sampled_drawdown_pct':25,'minimum_3x_adjacent_neighbor_positive_fraction':0.60,'minimum_1x_round_trips':4,'minimum_1x_gross_reference_pnl_to_cost':2.5,'zero_exchange_or_capacity_rejections':True,'terminal_flat_all_scenarios':True}
old=ROOT/'research/experiments/20261013T123949Z/report.json';old_report=json.loads(old.read_text())
registry_path=ROOT/'research/automation/registry.jsonl';records=registry.read_records(registry_path)
initial=json.loads((ROOT/'research/experiments/20261012T035429Z/prior_evidence_audit.json').read_text())
plan={'round':R.name,'frozen_at_utc':utc(),'status':'frozen_before_evaluation','direction':'Daily long-only fast/slow recursive EMA trend-state crossover, tested separately on BTC and ETH.','hypothesis':'A faster recursive trend state above a slower one may keep the spot account invested during persistent advances and move it to cash after trend deterioration. This is a deterministic, fixed-rule stress test, not a claim of an edge. Prior 15m EMA-cross results were strongly negative; daily spans and a complete predeclared surface test a slower horizon without selecting from this OOS.','literature_context':[{'citation':'Technical trading rules in the cryptocurrency market (2019), daily simple moving-average rules on 11 cryptocurrencies, 2016–2018.','url':'https://www.sciencedirect.com/science/article/pii/S1544612319308852','accessed_utc':'2026-10-14','scope':'Motivates a daily trend-rule falsification test; not evidence for this EMA rule or modern OOS profitability.'},{'citation':'Technical analysis in cryptocurrency markets: Do transaction costs and bubbles matter? (2022), daily/1m moving-average and breakout rules with/without transaction costs.','url':'https://www.sciencedirect.com/science/article/pii/S1042443122000816','accessed_utc':'2026-10-14','scope':'Motivates full cost testing; not a rule replication.'}],'prior_work':{'initial16':'research/experiments/20261012T035429Z/prior_evidence_audit.json verifies actual reports for all initial 16; no engineering-only row is pending backfill.','adjacent':'Repository has daily SMA/EMA hysteresis, close-channel EMA filters, volume/channel breakouts, volatility management, compression breakouts, failed-breakdown reclaim, and BTC/ETH lead-lag studies. This round tests a simple relative recursive EMA state crossover with a new daily span grid.','legacy_ema':'The legacy 20/50 EMA crossover is a 15m config; archived 1y fixed EMA-cross returns were -34.05% BTC and -29.93% ETH. It is contextual caution, not evidence for this new daily grid.','history':'The 2025-09-16 through 2026-09-16 archive has been repeatedly reused; this OOS window is not untouched. The registry contains extensive multiple testing; no DSR/PBO claim.'},'data':{'assets':data_files,'source_round':'research/experiments/20261013T164415Z/plan.json','exchange_info_source':'research/paper10/observations/20261014T081319010144Z/exchange_info.json.gz','exchange_info_raw_sha256':sha(raw_path),'oos_start_utc':start,'oos_end_exclusive_utc':end,'terminal_execution_utc':end,'start_day_index':368,'end_day_index':728,'oos_days':360,'folds':12,'fold_days':30,'warmup_days':365,'history_reused':True,'market':'Binance spot archived 1m OHLCV aggregated into continuous UTC daily closes; historical execution reference is next-day 00:01 1m open.'},'portfolio':{'capital_per_configuration_usdt':2000,'raw_weight':1.0,'weight_semantics':'100% single-asset sleeve for the named asset; BTC and ETH are separate configurations, not a combined portfolio.','no_transfer':True,'no_rebalance':True},'rule':rule,'grid':{'assets':assets,'fast_ema_spans_days':fast_spans,'slow_ema_spans_days':slow_spans,'all_fast_spans_below_slow':True,'configurations_per_asset':9,'total_configurations':18,'sensitivity_axes':['fast_ema_spans_days','slow_ema_spans_days']},'cost_model':cost,'exchange_rules':{'file':'research/experiments/'+R.name+'/exchange_filters.json','raw_sha256':sha(raw_path),'captured_at_utc':source['received_at_utc'],'filters_by_asset':{a:list(exchange['filters'][a]) for a in ('BTC','ETH')}},'walk_forward':{'folds':12,'fold_days':30,'continuous_account_across_folds':True,'fitted_model':False,'signal_uses_only_closed_UTC_bars':True,'purge_embargo':'No model fitting or forward labels; deterministic signal uses only closed bars. Warmup is strictly prior data.','holdout_disclosure':'Repeated repository development/OOS history, not an untouched final holdout.'},'failure_gates':gates,'benchmark_read_only':{'source_report':'research/experiments/20261013T123949Z/report.json','configurations':{'BTC':'hold_360d_btc_relative_strength_study','ETH':'hold_360d_eth_relative_strength_study'},'recalculate':False},'prior_registry_snapshot':{'events':len(registry.read_events(registry_path)),'unique_fingerprints':len(records),'initial16_missing':initial.get('missing_initial16',[]),'legacy_ema_cross_rows':sum(x.get('spec',{}).get('family')=='ema-cross' for x in records.values())}}
plan_path=R/'plan.json'
if plan_path.exists():
 frozen=json.loads(plan_path.read_text());candidate=dict(plan);candidate['frozen_at_utc']=frozen['frozen_at_utc'];assert candidate==frozen,'frozen plan differs from prepared inputs; retain plan and resolve manually';plan=frozen
else:write(plan_path,plan)
batch=[];reservations=[];seen=set()
for asset in assets:
 for f in fast_spans:
  for s in slow_spans:
   name=f'ema_cross_daily_{asset}_f{f}_s{s}'
   params={'asset':asset,'fast_ema_span_days':f,'slow_ema_span_days':s,'initial_capital_usdt':2000,'raw_initial_weight':1.0,'start_utc':start,'end_exclusive_utc':end,'terminal_execution_utc':end,'folds':12,'fold_days':30,'cost_multipliers':[1,2,3],'exchange_info_raw_sha256':sha(raw_path)}
   spec={'kind':'strategy','family':'spot-daily-ema-fast-slow-crossover-long-only','market':'spot','universe':[asset+'/USDT'],'timeframe':'1d','name':name,'logic':rule,'parameters':params,'validation_plan':str((R/'plan.json').relative_to(ROOT)),'sources':plan['literature_context']}
   fp=registry.fingerprint(spec);assert fp not in seen and not (records.get(fp) and records[fp].get('result_available') is True),(name,fp);seen.add(fp)
   path=R/'specs'/(name+'.json');write(path,spec)
   run=subprocess.run([sys.executable,str(ROOT/'research/automation/registry.py'),'reserve',str(path.relative_to(ROOT))],cwd=ROOT,text=True,capture_output=True)
   reservations.append({'name':name,'fingerprint':fp,'returncode':run.returncode,'stdout':run.stdout.strip(),'stderr':run.stderr.strip()})
   if run.returncode:write(R/'reserve_partial.json',reservations);raise SystemExit('reserve failed '+name+' '+run.stdout+run.stderr)
   batch.append({'name':name,'asset':asset,'fast':f,'slow':s,'fingerprint':fp,'spec':str(path.relative_to(ROOT))})
write(R/'batch.json',batch);write(R/'reserve.json',reservations)
print(json.dumps({'frozen':True,'configurations':len(batch),'per_asset':9,'plan_sha256':sha(R/'plan.json'),'exchange_info_sha256':sha(raw_path),'initial16_missing':initial.get('missing_initial16',[]),'prior_registry_configs':len(records)},ensure_ascii=False))
